import unittest
from solution import authorized_route


class TestRoute(unittest.TestCase):
    def test_exact_and_child(self):
        self.assertTrue(authorized_route('/admin', 'secret', 'secret'))
        self.assertTrue(authorized_route('/admin/users', 'secret', 'secret'))

    def test_prefix_and_traversal_rejected(self):
        self.assertFalse(authorized_route('/administrator', 'secret', 'secret'))
        self.assertFalse(authorized_route('/admin/../public', 'secret', 'secret'))

    def test_token_must_match(self):
        self.assertFalse(authorized_route('/admin', 'secret ', 'secret'))
        self.assertFalse(authorized_route('/admin', None, 'secret'))


if __name__ == '__main__':
    unittest.main()
